mapper.select:
SELECT
    (
        SELECT COALESCE(COUNT(*), 0)
        FROM TB_BASICFILEGROUP
        WHERE BASIC_CODE = #{basicCode}
          AND GROUP_TIMEGUBUN = 'TIME_INPUT_2'
          AND (TO_CHAR(TO_TIMESTAMP(GROUP_STARTTIME, 'HH24:MI') + INTERVAL '1 minute', 'HH24MI') BETWEEN #{groupStarttime} AND #{groupEndtime}
            OR TO_CHAR(TO_TIMESTAMP(GROUP_ENDTIME, 'HH24:MI') - INTERVAL '1 minute', 'HH24MI') BETWEEN #{groupStarttime} AND #{groupEndtime})
    ) AS timeCnt,
    (
        SELECT COALESCE(COUNT(*), 0)
        FROM TB_BASICFILEGROUP
        WHERE BASIC_CODE = #{basicCode}
          AND GROUP_TIMEGUBUN = 'TIME_INPUT_1'
    ) AS inutCnt
